// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;

    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e30);

        // Attacker helper (re-entrant counterparty)
        Attacker attacker = new Attacker(c);
        address other = address(0x1234);

        // 'other' user deposits `amount`
        vm.deal(other, amount);
        vm.prank(other);
        c.addToBalance{value: amount}();

        // Attacker deposits `amount`
        vm.deal(address(attacker), amount);
        attacker.deposit(amount);

        // Attacker withdraws; its receive() re-enters withdrawBalance.
        attacker.attack();

        // General rule: after a withdrawal completes, the contract still holds
        // the OTHER users' balances (re-entrant withdrawal must have failed).
        // P: balance == amount. M: re-entry drains it -> balance == 0.
        assertTrue(address(c).balance == amount);
    }
}

contract Attacker {
    Reentrance c;
    constructor(Reentrance _c) { c = _c; }

    function deposit(uint256 amt) external payable {
        address(c).call{value: amt}(abi.encodeWithSignature("addToBalance()"));
    }

    function attack() external {
        address(c).call(abi.encodeWithSignature("withdrawBalance()"));
    }

    receive() external payable {
        // re-enter; in P this reverts (mutex), in M it succeeds and drains funds
        address(c).call(abi.encodeWithSignature("withdrawBalance()"));
    }
}
